pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.assume(actor != address(c) && actor != address(this));
        vm.deal(actor, amount * 2);

        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdrawAll();

        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
